package gcache

import (
	"time"
)

// Fixed version of getWithLoader with proper stats tracking
func (c *LRUCache) getWithLoaderFixed(key interface{}, isWait bool) (interface{}, error) {
	if c.loaderExpireFunc == nil {
		return nil, KeyNotFoundError
	}
	value, _, err := c.load(key, func(v interface{}, expiration *time.Duration, e error) (interface{}, error) {
